const input = $input.first().json;
const PIPELINE_ID = '67c831a51f27cfb9fc9b13d3';
const qt = input.query_type || 'pipeline_summary';
const fv = input.filter_value || '';

let url = '';
const method = 'GET';

switch (qt) {
  case 'pipeline_summary':
    url = 'https://api.brevo.com/v3/crm/pipeline/' + PIPELINE_ID;
    break;
  case 'deals_by_stage':
    url = 'https://api.brevo.com/v3/crm/deals?filters[attributes.deal_stage]=' + fv;
    break;
  case 'all_deals':
    url = 'https://api.brevo.com/v3/crm/deals?limit=50';
    break;
  case 'contact_search':
    url = 'https://api.brevo.com/v3/contacts/' + encodeURIComponent(fv);
    break;
  case 'contacts_recent': {
    const days = parseInt(fv) || 7;
    const since = new Date(Date.now() - days * 86400000).toISOString();
    url = 'https://api.brevo.com/v3/contacts?limit=50&modifiedSince=' + since;
    break;
  }
  default:
    url = 'https://api.brevo.com/v3/crm/deals?limit=20';
}

return [{ json: { url, method, query_type: qt } }];

const response = $input.first().json;
const qt = $('Router Brevo API').first().json.query_type;

// Check for error from HTTP node (continueOnFail)
if (response.error || response.statusCode >= 400) {
  const errMsg = response.error || response.message || 'Erreur API Brevo (HTTP ' + (response.statusCode || '?') + ')';
  return [{ json: { formatted: 'Erreur Brevo: ' + errMsg, count: 0 } }];
}

let formatted = '';
let count = 0;

switch (qt) {
  case 'pipeline_summary': {
    const pipeline = response;
    const name = pipeline.pipeline_name || pipeline.name || 'Pipeline';
    formatted = '**Pipeline: ' + name + '**\n';
    if (pipeline.stages && Array.isArray(pipeline.stages)) {
      count = pipeline.stages.length;
      pipeline.stages.forEach(s => {
        formatted += '- ' + (s.name || s.id) + '\n';
      });
    } else {
      formatted += '(aucun stage trouve)\n';
    }
    break;
  }
  case 'deals_by_stage':
  case 'all_deals': {
    const deals = response.items || response.deals || [];
    count = deals.length;
    formatted = '**Deals (' + count + ')**\n';
    deals.forEach(d => {
      const name = d.attributes?.deal_name || d.name || d.id;
      const stage = d.attributes?.deal_stage || '-';
      const amount = d.attributes?.amount || d.amount || 0;
      formatted += '- ' + name + ' | Stage: ' + stage + ' | ' + amount + ' EUR\n';
    });
    if (count === 0) formatted += '(aucun deal)\n';
    break;
  }
  case 'contact_search': {
    count = 1;
    const c = response;
    const email = c.email || '-';
    const name = (c.attributes?.PRENOM || '') + ' ' + (c.attributes?.NOM || '');
    const company = c.attributes?.SOCIETE || c.attributes?.SMS || '-';
    formatted = '**Contact**\n';
    formatted += '- Nom: ' + name.trim() + '\n';
    formatted += '- Email: ' + email + '\n';
    formatted += '- Entreprise: ' + company + '\n';
    break;
  }
  case 'contacts_recent': {
    const contacts = response.contacts || [];
    count = contacts.length;
    formatted = '**Contacts recents (' + count + ')**\n';
    contacts.forEach(c => {
      const email = c.email || '-';
      const name = (c.attributes?.PRENOM || '') + ' ' + (c.attributes?.NOM || '');
      formatted += '- ' + name.trim() + ' (' + email + ')\n';
    });
    if (count === 0) formatted += '(aucun contact recent)\n';
    break;
  }
  default:
    formatted = 'Type de requete non reconnu: ' + qt;
}

// Truncate for Discord (1900 chars max)
if (formatted.length > 1900) {
  formatted = formatted.substring(0, 1897) + '...';
}

return [{ json: { formatted, count } }];
